Value.Calculation:
Let ( [

// Find the account whose Tracking Prefix this order's tracking number starts
// with. Prefixes live on the Account record (comma-separated when there is more
// than one) and are edited on the Accounts tab. Case does not matter.
// Longest prefix wins; an active account beats an inactive one.
// Returns the account in portal format - "Name (PrintSmith Account #NNNNN)" -
// so the portal and number calcs treat it exactly like a webhook portal.

~trk = Trim ( JSONGetElementValid ( PrinterPresence::messageClean ; "payload.message.message_tracking_number" ) ) ;
~raw = If ( IsEmpty ( ~trk ) ; "" ;
	ExecuteSQL ( " select \"TrackingPrefix\", \"Name\", \"AccountNumber\", \"fActive\" from \"Account\" where \"TrackingPrefix\" is not null " ; Char ( 31 ) ; Char ( 30 ) ) ) ;
~ok = not IsEmpty ( ~raw ) and Left ( ~raw ; 1 ) ≠ "?" ;
~rows = Substitute ( ~raw ; [ ¶ ; " " ] ; [ Char ( 30 ) ; ¶ ] ) ;
~n = If ( ~ok ; ValueCount ( ~rows ) ; 0 )

] ;

While (
	[ ~i = 1 ; ~best = 0 ; ~out = "" ] ;
	~i ≤ ~n ;
	[
		~r = Substitute ( GetValue ( ~rows ; ~i ) ; Char ( 31 ) ; ¶ ) ;
		~pfx = Substitute ( GetValue ( ~r ; 1 ) ; "," ; ¶ ) ;
		~name = Trim ( GetValue ( ~r ; 2 ) ) ;
		~num = Trim ( GetValue ( ~r ; 3 ) ) ;
		~act = GetAsNumber ( GetValue ( ~r ; 4 ) ) = 1 ;

		// length of the longest of this account's prefixes that matches, else 0
		~len = While (
			[ ~j = 1 ; ~m = 0 ] ;
			~j ≤ ValueCount ( ~pfx ) ;
			[
				~p = Trim ( GetValue ( ~pfx ; ~j ) ) ;
				~m = If ( not IsEmpty ( ~p ) and Length ( ~p ) > ~m and Left ( ~trk ; Length ( ~p ) ) = ~p ; Length ( ~p ) ; ~m ) ;
				~j = ~j + 1
			] ;
			~m
		) ;

		~score = If ( ~len > 0 ; ~len + ~act * 1000 ; 0 ) ;
		~out = If ( ~score > ~best ;
			Case (
				IsEmpty ( ~name ) ; "PrintSmith Account #" & ~num ;
				PatternCount ( ~name ; "#" & ~num ) ; ~name ;
				~name & " (PrintSmith Account #" & ~num & ")"
			) ;
			~out ) ;
		~best = Max ( ~best ; ~score ) ;
		~i = ~i + 1
	] ;
	~out
)

)
